package com.client.multichatwindows.config.ui; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.client.gui.screen.Screen; import net.minecraft.text.Text; import java.lang.reflect.Method; public class DarkScreen extends Screen { protected DarkScreen(Text title){super(title);} @Override public void render(DrawContext ctx,int mouseX,int mouseY,float delta){renderDarkBackground(ctx);super.render(ctx,mouseX,mouseY,delta);} protected void renderDarkBackground(DrawContext ctx){MinecraftClient mc=MinecraftClient.getInstance(); if(mc.getCurrentServerEntry()!=null&&tryRenderInGameBlur(ctx)){ctx.fill(0,0,width,height,0x99000000);return;} ctx.fill(0,0,width,height,0xFF0F0F10); ctx.fill(0,0,width,height,0x55000000);} private boolean tryRenderInGameBlur(DrawContext ctx){try{Method m=Screen.class.getDeclaredMethod("renderInGameBackground",DrawContext.class);m.setAccessible(true);m.invoke(this,ctx);return true;}catch(Throwable ignored){return false;}} }
